      <td>${row.name || "N/A"}</td>
      <td class="text-right">${row.quantity || 0}</td>
      <td class="text-right">${row.rate || "-"}</td>
      <td class="text-right">${row.cost || "-"}</td>
      <td class="text-right">${formatNumber(row.qty_used) || "-"}</td>
